  xm17 N012 Vbias3 P001 0 sky130_fd_pr__nfet_01v8 w={W_xm17} l={L_xm17}
  xm18 P001 N012 0 0 sky130_fd_pr__nfet_01v8 w={W_xm18} l={L_xm18}
.ends SUB_1

* Input voltage source: 0.9V DC nominal with AC and small-signal pulse for transient
Vin vin 0 dc 0.9 ac 1 pulse(0.895 0.905 500n 1n 1n 200n 500n)

* Control Block
.control
save all

* 1. Operating Point Analysis
op
let power = -i(VDD) * 1.8
print power

* 2. DC Transfer Analysis (Output swing and systematic offset)
dc Vin 0 1.8 0.01
meas dc vout_at_mid find v(vout) at=0.9
let sys_offset = 0.9 - vout_at_mid
print sys_offset
meas dc v_out_min min v(vout)
meas dc v_out_max max v(vout)

* 3. AC Frequency Response (Follower bandwidth)
ac dec 100 1k 1G
let cl_gain_db = vdb(vout)
meas ac cl_gain_mid find cl_gain_db at=10k
meas ac f_3db when cl_gain_db=-3 fall=1

* 4. Transient Small-Signal Step Response
tran 0.5n 1u
meas tran v_init find v(vout) at=499n
meas tran v_peak max v(vout) from=500n to=700n
meas tran t_settle trig v(vin) val=0.900 rise=1 targ v(vout) val=0.904 rise=1

quit
.endc
.end

